package com.creativeblisslabs.peqlearn.app.util

/**
 * Authoritative Chord Library derived from react-chords (tombatossals/react-chords)
 * and optilude/guitar-practice.
 * Contains over 3,200 guitar chord voicings and 2,100 ukulele chord voicings.
 */
data class RealChordPosition(
    val frets: List<Int>,
    val fingers: List<Int>,
    val baseFret: Int = 1,
    val barres: List<Int> = emptyList(),
    val capo: Boolean = false,
    val midi: List<Int> = emptyList()
)

object RealChordsDb {

    fun parsePosition(raw: String): RealChordPosition {
        val parts = raw.split("|")
        val frets = parts[0].split(",").mapNotNull { it.toIntOrNull() }
        val fingers = parts[1].split(",").mapNotNull { it.toIntOrNull() }
        val baseFret = parts.getOrNull(2)?.toIntOrNull() ?: 1
        val barres = parts.getOrNull(3)?.split(",")?.mapNotNull { it.toIntOrNull() } ?: emptyList()
        val capo = parts.getOrNull(4) == "1"
        val midi = parts.getOrNull(5)?.split(",")?.mapNotNull { it.toIntOrNull() } ?: emptyList()
        return RealChordPosition(
            frets = frets,
            fingers = fingers,
            baseFret = baseFret,
            barres = barres,
            capo = capo,
            midi = midi
        )
    }

