    private val guitarMap: Map<String, Map<String, List<RealChordPosition>>> by lazy {
        mapOf(
            "C" to getGuitarC(),
            "C#" to getGuitarCs(),
            "D" to getGuitarD(),
            "D#" to getGuitarDs(),
            "E" to getGuitarE(),
            "F" to getGuitarF(),
            "F#" to getGuitarFs(),
            "G" to getGuitarG(),
            "G#" to getGuitarGs(),
            "A" to getGuitarA(),
            "A#" to getGuitarAs(),
            "B" to getGuitarB(),
        )
    }

    private val ukeMap: Map<String, Map<String, List<RealChordPosition>>> by lazy {
        mapOf(
            "C" to getUkeC(),
            "C#" to getUkeCs(),
            "D" to getUkeD(),
            "D#" to getUkeDs(),
            "E" to getUkeE(),
            "F" to getUkeF(),
            "F#" to getUkeFs(),
            "G" to getUkeG(),
            "G#" to getUkeGs(),
            "A" to getUkeA(),
            "A#" to getUkeAs(),
            "B" to getUkeB(),
        )
    }

    fun getGuitarPositions(root: String, suffix: String): List<RealChordPosition> {
        val normRoot = normalizeRoot(root)
        val normSuffix = normalizeSuffix(suffix)
        val forRoot = guitarMap[normRoot] ?: return emptyList()
        return forRoot[normSuffix] 
            ?: forRoot[suffix.lowercase()]
            ?: forRoot["major"]
            ?: emptyList()
    }

    fun getUkulelePositions(root: String, suffix: String): List<RealChordPosition> {
        val normRoot = normalizeRoot(root)
        val normSuffix = normalizeSuffix(suffix)
        val forRoot = ukeMap[normRoot] ?: return emptyList()
        return forRoot[normSuffix] 
            ?: forRoot[suffix.lowercase()]
            ?: forRoot["major"]
            ?: emptyList()
    }

    fun getAvailableSuffixes(instrument: String = "guitar"): List<String> {
        val refKey = "C"
        return if (instrument.lowercase() == "ukulele" || instrument.lowercase() == "uke") {
            ukeMap[refKey]?.keys?.toList() ?: emptyList()
        } else {
            guitarMap[refKey]?.keys?.toList() ?: emptyList()
        }
    }

    fun normalizeRoot(root: String): String {
        return when (root.uppercase().replace("♯", "#").replace("♭", "b")) {
            "DB" -> "C#"
            "EB" -> "D#"
            "GB" -> "F#"
            "AB" -> "G#"
            "BB" -> "A#"
            else -> root.replace("♯", "#").replace("♭", "b").replaceFirstChar { it.uppercase() }
        }
    }

    fun normalizeSuffix(suffix: String): String {
        val s = suffix.trim().lowercase()
        return when (s) {
            "", "maj", "major", "m", "triangle" -> "major"
            "min", "minor", "-" -> "minor"
            "dom7", "7" -> "7"
            "m7", "min7", "minor7", "-7" -> "m7"
            "maj7", "major7", "delta7" -> "maj7"
            "dim", "o" -> "dim"
            "dim7", "o7" -> "dim7"
            "m7b5", "half-dim", "ø" -> "m7b5"
            "aug", "+" -> "aug"
            "aug7", "+7" -> "aug7"
            "sus4", "sus" -> "sus4"
            "sus2" -> "sus2"
            "7sus4" -> "7sus4"
            "6" -> "6"
            "m6" -> "m6"
            "69", "6/9" -> "69"
            "m69", "m6/9" -> "m69"
            "9" -> "9"
            "maj9" -> "maj9"
            "m9" -> "m9"
            "add9" -> "add9"
            "madd9" -> "madd9"
            "11" -> "11"
            "maj11" -> "maj11"
            "m11" -> "m11"
            "13" -> "13"
            "maj13" -> "maj13"
            "5", "power" -> "5"
            else -> s
        }
    }
}
